def build_diff(self, want, have):
    """
    Builds a dictionary of differences between the want and have objects.
    """
    diff = {}
    for key in self.want.api_map:
        if self.want.api_map[key] in self.want.updatables:
            if self.compare(key)!= self.have.api_map[key]:
                diff[key] = self.compare(key)
    return diff
